export const DEFAULT_APPEARANCE={name:'Mon artisan',kind:'human',skin:'#d9ab86',hair:'#614b42',sweater:'#7ea68d',pants:'#526b72',hat:'beanie',hatColor:'#d98962',apron:true,glasses:false};
export const PALETTES={skin:['#f0cfad','#d9ab86','#b8805b','#865d48','#5e4036','#d99553'],hair:['#614b42','#332f31','#ad754c','#d5b879','#aeb6b1','#b98295'],sweater:['#7ea68d','#cf846f','#c3a163','#9993b4','#77a6b3','#e0b7a1'],pants:['#526b72','#695e6a','#7b8065','#a1896d'],hatColor:['#d98962','#7b9b79','#9f94b8','#c8ab70','#789aaa','#b87788']};
export function normalizeAppearance(input){const a=input&&typeof input==='object'?input:{};const result={...DEFAULT_APPEARANCE};result.name=typeof a.name==='string'?(a.name.trim().slice(0,24)||DEFAULT_APPEARANCE.name):DEFAULT_APPEARANCE.name;result.kind=['human','fox'].includes(a.kind)?a.kind:DEFAULT_APPEARANCE.kind;result.hat=['beanie','cap','wizard','none'].includes(a.hat)?a.hat:DEFAULT_APPEARANCE.hat;for(const key of ['skin','hair','sweater','pants','hatColor'])result[key]=typeof a[key]==='string'&&/^#[0-9a-f]{6}$/i.test(a[key])?a[key]:DEFAULT_APPEARANCE[key];result.apron=a.apron!==false;result.glasses=a.glasses===true;return result;}
